@Override public void onHeaderDecoded(@NonNull ImageDecoder decoder, @NonNull ImageDecoder.ImageInfo info, @NonNull ImageDecoder.Source source) {
  int factor = 1;
  while (info.getSize().getWidth() / factor > scaleToPixels) {
    factor *= 2;
  }
  try {
    decoder.setTargetSampleSize(factor);
  } catch (IllegalArgumentException e) {
    // Handle invalid sample size, e.g., log and set a safe default
    decoder.setTargetSampleSize(1);
  }
}
